/* ---------- PDF kao pravi tekst (vektor, ugrađen font) ---------- */
const FNT={r:"",b:""};
function pdfU8(b){const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u}
function pdfTTF(u8){
  const dv=new DataView(u8.buffer,u8.byteOffset,u8.byteLength),T={},nt=dv.getUint16(4);
  for(let i=0;i<nt;i++){const o=12+i*16;T[String.fromCharCode(u8[o],u8[o+1],u8[o+2],u8[o+3])]={o:dv.getUint32(o+8)}}
  const upem=dv.getUint16(T.head.o+18),nh=dv.getUint16(T.hhea.o+34),ng=dv.getUint16(T.maxp.o+4),adv=[];let last=0;
  for(let g=0;g<ng;g++){if(g<nh)last=dv.getUint16(T.hmtx.o+g*4);adv.push(last)}
  const map=new Map(),co=T.cmap.o,nc=dv.getUint16(co+2);let o4=-1,o12=-1;
  for(let i=0;i<nc;i++){const off=co+dv.getUint32(co+8+i*8),f=dv.getUint16(off);if(f===12)o12=off;else if(f===4&&o4<0)o4=off}
  if(o12>=0){const n=dv.getUint32(o12+12);for(let i=0;i<n;i++){const p=o12+16+i*12,s=dv.getUint32(p),e=dv.getUint32(p+4),g=dv.getUint32(p+8);for(let c=s;c<=e;c++)map.set(c,g+c-s)}}
  else if(o4>=0){const sc=dv.getUint16(o4+6)/2,eO=o4+14,sO=eO+sc*2+2,dO=sO+sc*2,rO=dO+sc*2;
    for(let s=0;s<sc;s++){const e=dv.getUint16(eO+s*2),st=dv.getUint16(sO+s*2),d=dv.getInt16(dO+s*2),ro=dv.getUint16(rO+s*2);
      for(let c=st;c<=e&&c<0xFFFF;c++){let g;if(ro===0)g=(c+d)&0xFFFF;else{g=dv.getUint16(rO+s*2+ro+(c-st)*2);if(g)g=(g+d)&0xFFFF}if(g)map.set(c,g)}}}
  return{u8,upem,adv,map};
}
function PdfDoc(){
  const F=[pdfTTF(pdfU8(FNT.r)),pdfTTF(pdfU8(FNT.b))],used=[new Map(),new Map()],pgs=[],sc=595.28/794,PH=841.89;
  let cur=null;
  const f2=n=>(+n).toFixed(2),cc=c=>[c.r,c.g,c.b].map(v=>(v/255).toFixed(3)).join(" ");
  const gid=(f,code)=>{const m=F[f].map;return m.get(code)||m.get(63)||0};
  return{
    addPage(){cur=[];pgs.push(cur)},
    rect(x,y,w,h,c){cur.push(cc(c)+" rg "+f2(x*sc)+" "+f2(PH-(y+h)*sc)+" "+f2(w*sc)+" "+f2(h*sc)+" re f")},
    width(s,fs,bold){let w=0;for(const ch of s){w+=F[bold?1:0].adv[gid(bold?1:0,ch.codePointAt(0))]}return w*fs/F[0].upem},
    text(x,y,fs,bold,c,s,ls,stroke){
      const f=bold?1:0;let hex="";
      for(const ch of s){const code=ch.codePointAt(0),g=gid(f,code);used[f].set(g,code>0xFFFF?63:code);hex+=g.toString(16).padStart(4,"0")}
      cur.push("BT /F"+f+" "+f2(fs*sc)+" Tf "+(stroke?"2 Tr "+f2(stroke*sc)+" w "+cc(c)+" RG ":"")+cc(c)+" rg "+f2((ls||0)*sc)+" Tc "+f2(x*sc)+" "+f2(PH-y*sc)+" Td <"+hex+"> Tj 0 Tr ET");
    },
    finish(){
      const enc=new TextEncoder(),O=[];
      const set=(n,b)=>{O[n-1]=enc.encode(n+" 0 obj\n"+b+"\nendobj\n")};
      const stream=(n,d,u8)=>{const h=enc.encode(n+" 0 obj\n<<"+d+" /Length "+u8.length+">>\nstream\n"),t=enc.encode("\nendstream\nendobj\n"),o=new Uint8Array(h.length+u8.length+t.length);o.set(h);o.set(u8,h.length);o.set(t,h.length+u8.length);O[n-1]=o};
      set(1,"<</Type/Catalog/Pages 2 0 R>>");
      for(let f=0;f<2;f++){
        const b=3+f*5,nm=f?"LiberationSans-Bold":"LiberationSans",Fo=F[f];
        set(b,"<</Type/Font/Subtype/Type0/BaseFont/"+nm+"/Encoding/Identity-H/DescendantFonts["+(b+1)+" 0 R]/ToUnicode "+(b+4)+" 0 R>>");
        set(b+1,"<</Type/Font/Subtype/CIDFontType2/BaseFont/"+nm+"/CIDSystemInfo<</Registry(Adobe)/Ordering(Identity)/Supplement 0>>/FontDescriptor "+(b+2)+" 0 R/CIDToGIDMap/Identity/DW 600/W[0["+Fo.adv.map(a=>Math.round(a*1000/Fo.upem)).join(" ")+"]]>>");
        set(b+2,"<</Type/FontDescriptor/FontName/"+nm+"/Flags 32/FontBBox[-200 -250 1200 950]/ItalicAngle 0/Ascent 905/Descent -212/CapHeight 716/StemV "+(f?120:80)+"/FontFile2 "+(b+3)+" 0 R>>");
        stream(b+3,"/Length1 "+Fo.u8.length,Fo.u8);
        const hx=n=>n.toString(16).padStart(4,"0").toUpperCase(),es=[...used[f]];
        let cm="/CIDInit /ProcSet findresource begin 12 dict begin begincmap /CIDSystemInfo<</Registry(Adobe)/Ordering(UCS)/Supplement 0>> def /CMapName/Adobe-Identity-UCS def /CMapType 2 def 1 begincodespacerange <0000> <FFFF> endcodespacerange\n";
        for(let i=0;i<es.length;i+=100){const ch=es.slice(i,i+100);cm+=ch.length+" beginbfchar\n"+ch.map(e=>"<"+hx(e[0])+"> <"+hx(e[1])+">").join("\n")+"\nendbfchar\n"}
        cm+="endcmap CMapName currentdict /CMap defineresource pop end end";
        stream(b+4,"",enc.encode(cm));
      }
      const n=pgs.length,kids=[];
      for(let i=0;i<n;i++){const p=13+i*2;kids.push(p+" 0 R");
        set(p,"<</Type/Page/Parent 2 0 R/MediaBox[0 0 595.28 841.89]/Resources<</Font<</F0 3 0 R/F1 8 0 R>>>>/Contents "+(p+1)+" 0 R>>");
        stream(p+1,"",enc.encode(pgs[i].join("\n")))}
      set(2,"<</Type/Pages/Kids["+kids.join(" ")+"]/Count "+n+">>");
      const hd=new Uint8Array([0x25,0x50,0x44,0x46,0x2D,0x31,0x2E,0x34,0x0A,0x25,0xE2,0xE3,0xCF,0xD3,0x0A]),offs=[];let len=hd.length;
      O.forEach(o=>{offs.push(len);len+=o.length});
      let xr="xref\n0 "+(O.length+1)+"\n0000000000 65535 f \n"+offs.map(o=>String(o).padStart(10,"0")+" 00000 n \n").join("");
      const tail=enc.encode(xr+"trailer\n<</Size "+(O.length+1)+"/Root 1 0 R>>\nstartxref\n"+len+"\n%%EOF"),out=new Uint8Array(len+tail.length);
      out.set(hd);let p=hd.length;O.forEach(o=>{out.set(o,p);p+=o.length});out.set(tail,len);return out;
    }
  };
}
function pdfCollect(root){
  const b0=root.getBoundingClientRect(),out=[],rg=document.createRange();
  const rgb=s=>{const m=/rgba?\(([^)]+)\)/.exec(s);if(!m)return null;const p=m[1].split(/[\s,\/]+/).filter(Boolean).map(Number),a=p.length>3?p[3]:1;if(!a)return null;const mx=v=>Math.round(v*a+255*(1-a));return{r:mx(p[0]),g:mx(p[1]),b:mx(p[2])}};
  (function walk(el,isRoot){
    const cs=getComputedStyle(el);if(cs.display==="none"||cs.visibility==="hidden")return;
    const r=el.getBoundingClientRect(),x=r.left-b0.left,y=r.top-b0.top;
    const bd=()=>[["Top",bw=>[x,y,r.width,bw]],["Bottom",bw=>[x,y+r.height-bw,r.width,bw]],["Left",bw=>[x,y,bw,r.height]],["Right",bw=>[x+r.width-bw,y,bw,r.height]]].forEach(([nm,f])=>{
      const bw=parseFloat(cs["border"+nm+"Width"]);if(bw>0&&cs["border"+nm+"Style"]!=="none"){const c=rgb(cs["border"+nm+"Color"]);if(c){const q=f(bw);out.push({k:"r",x:q[0],y:q[1],w:q[2],h:q[3],c})}}});
    let late=false;
    if(r.width>0&&r.height>0){
      const bg=isRoot?null:rgb(cs.backgroundColor);if(bg)out.push({k:"r",x,y,w:r.width,h:r.height,c:bg});
      late=el.tagName==="TABLE";if(!late)bd();
    }
    for(const n of el.childNodes){
      if(n.nodeType===1)walk(n,false);
      else if(n.nodeType===3&&n.data.trim()){
        const fs=parseFloat(cs.fontSize),fw=parseInt(cs.fontWeight)||400,c=rgb(cs.color)||{r:0,g:0,b:0},up=cs.textTransform==="uppercase",ls=parseFloat(cs.letterSpacing)||0,lines=[];let line=null;
        for(let i=0;i<n.data.length;i++){
          const ch=n.data[i];rg.setStart(n,i);rg.setEnd(n,i+1);const rs=rg.getClientRects();if(!rs.length)continue;const q=rs[0],ws=/\s/.test(ch);
          if(ws&&q.width<0.01)continue;
          if(!line||q.top>line.top+fs*0.6){if(ws)continue;line={top:q.top,x:q.left,s:""};lines.push(line)}
          line.s+=ws?" ":ch;
        }
        lines.forEach(L=>{let s=L.s.replace(/\s+$/,"");if(!s)return;if(up)s=s.toUpperCase();out.push({k:"t",x:L.x-b0.left,y:L.top-b0.top+fs*0.905,top:L.top-b0.top,fs,bold:fw>=600,c,s,ls,stroke:fw>=850?fs*0.035:0})});
      }
    }
    if(late)bd();
  })(root,true);
  return out;
}
async function pdfOf(fname,S){
  let wrap=null;
  try{
    S.textContent="Pravim PDF…";
    const dl=await claude.use("downloads");if(!dl){S.textContent="Preuzimanje nije dostupno u ovom prikazu.";return}
    const W=794,H=1123;
    wrap=document.createElement("div");wrap.style.cssText="position:absolute;left:-10000px;top:0;width:794px;background:#fff";
    const cl=$("sheet").cloneNode(true);cl.style.cssText="width:794px;max-width:794px;border:0;margin:0";
    wrap.appendChild(cl);document.body.appendChild(wrap);
    const ft=cl.querySelector(".sfoot"),sg=cl.querySelector(".sigblock");
    let fi=[],fh=0,si=[],sh=0;
    if(ft){ft.style.marginTop="0";fh=ft.offsetHeight;fi=pdfCollect(ft);ft.remove()}
    if(sg){sg.style.marginTop="0";sh=sg.offsetHeight;si=pdfCollect(sg);sg.remove()}
    const base=cl.getBoundingClientRect().top,cuts=[];
    cl.querySelectorAll("tbody tr,tfoot tr,.sg,.hd,.bn,.nt").forEach(el=>{if(el.tagName==="TR"&&el.closest(".ns"))return;cuts.push(Math.round(el.getBoundingClientRect().bottom-base))});
    const total=Math.ceil(cl.getBoundingClientRect().height);
    const items=pdfCollect(cl);
    const bottom=H-fh-12,limit=bottom-10;
    const pages=[];let y=0;
    while(y<total-1){
      const top=pages.length?24:0,avail=limit-top;let end=Math.min(total,y+avail);
      if(end<total){const c=cuts.filter(v=>v>y+40&&v<=end);if(c.length)end=Math.max(...c)}
      else if(si.length&&top+(total-y)+sh+20>limit){const c=cuts.filter(v=>v>y+40&&v<total-5);if(c.length)end=Math.max(...c)}
      pages.push({y,end,top});y=end;
    }
    if(!pages.length)pages.push({y:0,end:total,top:0});
    if(si.length){const L=pages[pages.length-1];if(L.top+(L.end-L.y)+sh+20>limit)pages.push({y:total,end:total,top:24})}
    const doc=PdfDoc(),draw=(list,ox,oy,y0,y1)=>list.forEach(it=>{
      if(it.k==="r"){const a=Math.max(it.y,y0),b=Math.min(it.y+it.h,y1);if(b>a)doc.rect(it.x+ox,a+oy,it.w,b-a,it.c)}
      else if(it.top>=y0-0.5&&it.top<y1-0.5)doc.text(it.x+ox,it.y+oy,it.fs,it.bold,it.c,it.s,it.ls,it.stroke);
    });
    pages.forEach((pg,i)=>{
      doc.addPage();
      draw(items,0,pg.top-pg.y,pg.y,pg.end);
      draw(fi,0,bottom,0,1e9);
      if(i===pages.length-1)draw(si,40,bottom-sh-20,0,1e9);
      if(pages.length>1){const t="Strana "+(i+1)+" / "+pages.length;doc.text(W-40-doc.width(t,12,false),bottom-6,12,false,{r:110,g:115,b:122},t,0,0)}
    });
    await dl.save({filename:fname,data:doc.finish().buffer});S.textContent="PDF sačuvan – otvori ga i štampaj.";
  }catch(e){S.textContent=(e&&e.code==="declined")?"":"PDF nije uspeo: "+((e&&(e.message||e.code))||"nepoznata greška")}
  finally{if(wrap)wrap.remove()}
}
$("pPrint").onclick=()=>printSheet(proSheet,$("pstatus"));
$("pPdf").onclick=()=>pdfOf("Predracun_"+pcur.no+"-"+pcur.year+"_"+pcur.customer.trim().replace(/\s+/g,"_")+".pdf",$("pstatus"));
$("pdv").value=20;

